new = '''def _deliver(router, v, rv, order, C, n, dist, recipes, memo):
    """Deliver rv units of v's chunks to every other participant, with relays.

    Returns (lv, flows) or None.
    """
    have = {}
    for (w, _rw) in [(x[0], x[1]) for x in C] if isinstance(C, list) else []:
        pass
    plist = C
    have = {p[0]: 0 for p in plist}
    have[v] = rv
    names = [p[0] for p in plist]
    lv = defaultdict(int)
    out = []
    senders_all = [v] + [w for w in names if w != v]
    for _p in range(4):
        progress = False
        for w in order:
            need = rv - have[w]
            if need <= 0:
                continue
            cands = [u for u in senders_all if have[u] > 0]
            cands.sort(key=lambda u: (dist.get((u, w), float('inf')), u))
            for u in cands:
                need = rv - have[w]
                if need <= 0:
                    break
                cap = min(have[u], need)
                if cap <= 0:
                    continue
                if dist.get((u, w), float('inf')) == float('inf'):
                    continue
                allowed = set(range(n)) - (set(names) - set([u, w]))
                fl = router.route_max(u, w, cap, allowed)
                if fl is None:
                    continue
                got = 0
                for (path, cnt) in fl:
                    rid = _recipe(path, recipes, memo)
                    if rid is None:
                        return None
                    out.append((u, w, cnt, rid))
                    got += cnt
                if got > 0:
                    lv[(u, w)] += got
                    have[w] += got
                    progress = True
        if all(have[w] >= rv for w in names):
            break
        if not progress:
            break
    if any(have[w] < rv for w in names):
        return None
    return (lv, out)


'''
src = src[:start] + new + src[end:]
